import{v as n,c as t,o as a,ae as r}from"./chunks/framework.B8KKhRA6.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"introduction/overview.md","filePath":"introduction/overview.md"}'),i={name:"introduction/overview.md"},g=Object.assign(i,{setup(s){return n(()=>{document.querySelectorAll('a[href="/duocodo.docx.html"]').forEach(e=>{e.setAttribute("href","javascript:void(0)"),e.addEventListener("click",l=>{location.href="/duocodo.docx"})})}),(o,e)=>(a(),t("div",null,e[0]||(e[0]=[r('<h2 id="project-overview" tabindex="-1">Project Overview <a class="header-anchor" href="#project-overview" aria-label="Permalink to &quot;Project Overview&quot;">​</a></h2><h3 id="problem-statement" tabindex="-1">Problem Statement <a class="header-anchor" href="#problem-statement" aria-label="Permalink to &quot;Problem Statement&quot;">​</a></h3><p>Learning programming can be overwhelming for beginners due to the fragmented nature of resources, lack of guided practice, and insufficient motivation or feedback loops. Many learners struggle to maintain consistency and confidence, especially when switching between theoretical concepts and practical application. Traditional educational platforms often fail to make the learning process engaging and personalized.</p><h3 id="solution-approach" tabindex="-1">Solution Approach <a class="header-anchor" href="#solution-approach" aria-label="Permalink to &quot;Solution Approach&quot;">​</a></h3><p>Our project aims to teach programming using an approach inspired by <strong>Duolingo</strong>—breaking down programming concepts into small, interactive lessons and combining them with gamified learning elements. The platform will support various programming domains, covering <strong>fundamentals to modular concepts</strong>. The learning process integrates <strong>explanations (via articles or videos)</strong> with <strong>hands-on coding exercises</strong>, <strong>problem-solving</strong>, <strong>code walkthroughs</strong>, and <strong>complexity analysis</strong>. Additionally, users can <strong>share their solutions</strong>, earn <strong>badges</strong>, and compete on leaderboards, fostering a vibrant and motivating learning environment.</p><h3 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h3><ul><li><strong>Duolingo-style progressive learning</strong>: Lessons are structured in a path-like format with levels and checkpoints.</li><li><strong>Multi-format content</strong>: Each concept includes an explanation in either video or article form.</li><li><strong>Integrated problem-solving</strong>: Practice problems with instant feedback, model answers, and full solution breakdowns.</li><li><strong>Code complexity analysis</strong>: Each solution is accompanied by performance and complexity discussions.</li><li><strong>Modular curriculum</strong>: Covers programming fundamentals as well as specialized modules (e.g., OOP, algorithms, web development).</li><li><strong>Gamification</strong>: Badges, streaks, and experience points to keep users engaged.</li><li><strong>Community engagement</strong>: Users can share solutions and view others&#39; approaches to promote peer learning.</li><li><strong>Competitive edge</strong>: Optional coding challenges and competitions with leaderboards.</li><li><strong>Clear progression tracking</strong>: Visual indicators of completed lessons, mastered topics, and pending modules.</li></ul>',7)])))}});export{d as __pageData,g as default};
